SET lock_timeout = '5s';

-- Redrawn Class Starter, Pre-Writing and Thesis Statement cards: the drawing
-- enlarged and the wordmark below it removed (the tile already prints the
-- title). Production does not run the card seeds, so this is how the new cards
-- reach it; seeded databases get them from the seeds' retired-md5 lists too.
--
-- Each UPDATE replaces a card only when it is one Yawp drew:
--   * the wordmark version of the card, on any assignment type. In
--     production the Thesis Statement wordmark card is also the image on
--     "The Thesis-Driven Essay", and that one is swapped too.
--   * an older seed drawing, on the type of that kind.
-- Anything else (a school's own upload) is left alone, and a database without
-- these rows is a no-op.

-- class_starter
UPDATE "AssignmentTypeImage" AS img
SET
  "updatedAt" = NOW(),
  "altText" = 'A scratchy ink drawing of a smiling cat holding a mug of coffee, on torn white paper.',
  "contentType" = 'image/jpeg',
  "blob" = decode(
    '',
    'base64'
  )
FROM "AssignmentType" AS t
WHERE img."assignmentTypeId" = t."id"
  AND (
    md5(img."blob") = 'f902670ff70ebcee17a0a733c5ad0248'
    OR (
      t."kind" = 'class_starter'
      AND md5(img."blob") IN (
    '429eac2e3a0b56f3140f6a8da4382101'
      )
    )
  );

-- prewriting
UPDATE "AssignmentTypeImage" AS img
SET
  "updatedAt" = NOW(),
  "altText" = 'A scratchy ink drawing of a dog in a beret and striped shirt with a lightbulb over its head, on torn white paper.',
  "contentType" = 'image/jpeg',
  "blob" = decode(
    '',
    'base64'
  )
FROM "AssignmentType" AS t
WHERE img."assignmentTypeId" = t."id"
  AND (
    md5(img."blob") = 'f903a3e91b54fc985e511c39a5e3c137'
    OR (
      t."kind" = 'prewriting'
      AND md5(img."blob") IN (
    '2e22d9bede4d3eee6d1ca26a446ef931',
    '0894136c31fa3eee303d703e72a3ba6c'
      )
    )
  );

-- thesis_statement
UPDATE "AssignmentTypeImage" AS img
SET
  "updatedAt" = NOW(),
  "altText" = 'A scratchy ink drawing of a dog in a beret and striped shirt saying yawp! in a speech bubble, on torn white paper.',
  "contentType" = 'image/jpeg',
  "blob" = decode(
    '',
    'base64'
  )
FROM "AssignmentType" AS t
WHERE img."assignmentTypeId" = t."id"
  AND (
    md5(img."blob") = 'd0d12c18db5bed8eefa47bb550de2ff9'
    OR (
      t."kind" = 'thesis_statement'
      AND md5(img."blob") IN (
    'c024adc8c638fbec53ac10bb4cb86d18',
    '8124afc102fdb63532b6602643dc193d'
      )
    )
  );
